#!/usr/bin/env bash
# Zion-Dashboard — per-repo validation gate (stack: node).
# Generated by tools/validate/generate.sh. Edit freely afterwards; the generator
# will not overwrite this file without --force.
#
#   quick   seconds. Manifest parse, lint, type-check.
#   full    minutes. Adds build and tests.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

check "package manifests are valid JSON" "python3" \
  'for f in package.json */package.json; do
     [ -f "$f" ] || continue
     python3 -c "import json,sys; json.load(open(sys.argv[1]))" "$f" \
       || { echo "invalid JSON: $f"; exit 1; }
   done'

# A lockfile that has drifted from package.json is how a build that works
# locally fails in CI with a different dependency tree.
assert "lockfile present alongside every manifest" \
  'for f in package.json */package.json; do
     [ -f "$f" ] || continue
     d=$(dirname "$f")
     [ -f "$d/package-lock.json" ] || [ -f "$d/pnpm-lock.yaml" ] || [ -f "$d/yarn.lock" ] \
       || { echo "no lockfile beside $f"; exit 1; }
   done'

# Dependencies must be installed for lint/type-check to mean anything; without
# node_modules they exit non-zero for a reason that has nothing to do with code.
if [ -d node_modules ] || [ -d webui/node_modules ]; then
  check "lint" "node npm" 'make lint'
else
  block "lint" "not run; no node_modules — run: make install"
fi

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

if [ -d node_modules ] || [ -d webui/node_modules ]; then
  check "build" "node npm" 'make build'
  check "tests" "node npm" 'make test'
else
  block "build" "not run; no node_modules — run: make install"
  block "tests" "not run; no node_modules — run: make install"
fi

report "$TIER"
